import fs from 'node:fs';import{pathToFileURL}from'node:url';
const base=new URL('.',pathToFileURL(process.argv[2]));const{McpHost}=await import(new URL('host.js',base));const{DeterministicLiveSimulator,LiveMutationNotDispatchedError}=await import(new URL('live.js',base));
function clean(v){v=structuredClone(v);function walk(x){if(!x||typeof x!=='object')return;for(const[k,w]of Object.entries(x)){if(typeof w==='string'&&w.startsWith('data_'))x[k]='$transaction';else if(k==='expiresAt')x[k]='$time';else walk(w);}}if(v?.result?.content?.[0]?.text)try{v.result.content[0].text=JSON.parse(v.result.content[0].text)}catch{}walk(v);return v}
const kinds=['set','track','clear-set','clear-track'];
const args=kind=>({key:'kumi.test',value:kind.startsWith('clear')?null:'new text',...(kind.endsWith('track')?{trackRef:'track:track-1'}:{})});
const owner=kind=>kind.endsWith('track')?'track:track-1':'set:set-1';

const rows=[];for(const action of ['preview','apply']){const valid=action==='preview'?args('set'):{transactionId:'missing',confirmation:'apply',idempotencyKey:'apply-key'};const cases=[null,[],{},0,false,'x',valid,{...valid,extra:true}];for(const key of action==='preview'?['key','value','trackRef']:Object.keys(valid)){const omitted={...valid};delete omitted[key];cases.push(omitted);for(const value of [null,[],{},false,true,-1,0,0.5,1,'','x','a'.repeat(257)])cases.push({...valid,[key]:value})}for(const p of cases){const sim=new DeterministicLiveSimulator(),host=new McpHost(sim);let result;try{result=clean(await host[action==='preview'?'liveDataPreviewAsync':'liveDataApplyAsync'](1,p))}catch(e){result={error:e.message}}rows.push({action,args:p,result})}}
const workflows=[];for(const kind of kinds)for(const scenario of ['normal','expire','epoch','identity-edit','data-edit','missing-identity','apply-before','apply-after','apply-refusal','apply-no-effect','apply-read','apply-current-read','apply-preabort','undo-before','undo-after','undo-refusal','undo-no-effect','undo-read','undo-current-read','undo-other-identity','undo-other-content','undo-epoch']){
const sim=new DeterministicLiveSimulator();sim.invoke({operation:'data.set',args:{ref:owner(kind),key:'kumi.test',value:'before'}});const calls=[],cache=new Map();let fault='',fired=false,afterInvoke=false;if(scenario==='missing-identity')sim.state.tracks[0].objectIdentity='';
function context(c){return c?{deadline:c.deadlineMs!==undefined,...(c.idempotencyKey?{idempotencyKey:c.idempotencyKey}:{}),...(c.transactionId?{transactionId:c.transactionId}:{})}:null}
function readFault(){if(!fired&&((fault.endsWith('-read')&&afterInvoke)||fault==='apply-current-read'||fault==='undo-current-read')){fired=true;throw Error('injected authoritative read failure')}}
function invoke(i,c){calls.push(clean({method:'invoke',invocation:i,context:context(c)}));const key=JSON.stringify([c?.transactionId,c?.idempotencyKey,i]);if(cache.has(key))return structuredClone(cache.get(key));if(!fired&&['before','refusal'].some(s=>fault.endsWith(s))){fired=true;throw fault.endsWith('refusal')?new LiveMutationNotDispatchedError('mutation was not dispatched: ownership changed'):Error('injected operation failure')}const noEffect=!fired&&fault.endsWith('no-effect');const result=noEffect?{ok:true}:sim.invoke(i);if(noEffect)fired=true;else cache.set(key,structuredClone(result));afterInvoke=true;if(!fired&&fault.endsWith('after')){fired=true;throw Error('injected operation failure')}if(!fired&&['apply-invalid-identity','apply-invalid-fingerprint','apply-settle'].includes(fault)){fired=true;result[fault.endsWith('identity')?'deviceObjectIdentity':'createdFingerprint']=fault==='apply-settle'?'settling':''}return result}
const adapter={status:()=>sim.status(),snapshot:()=>sim.snapshot(),get:r=>sim.get(r),invoke:i=>invoke(i),subscribe:l=>sim.subscribe(l),reconnect:()=>sim.reconnect(),snapshotAsync:async(c,r)=>{calls.push(clean({method:'snapshot',request:r??null,context:context(c)}));readFault();return sim.snapshotAsync(c,r)},discoverAsync:async(r,c)=>{calls.push(clean({method:'discover',request:r,context:context(c)}));readFault();return sim.discoverAsync(r,c)},getAsync:async(r,c)=>{calls.push(clean({method:'get',reference:r,context:context(c)}));readFault();return sim.get(r)},invokeAsync:async(i,c)=>invoke(i,c),refreshStatusAsync:async c=>{calls.push(clean({method:'status',context:context(c)}));return sim.status()}};
const host=new McpHost(adapter),results=[],states=[];const preview=await host.liveDataPreviewAsync(1,args(kind));results.push(clean(preview));const body=JSON.parse(preview.result.content[0].text);const txid=body.transactionId;
if(txid){const record=host.clipLifecycleTransactions.get(txid);async function perform(action,key){const p={transactionId:txid,confirmation:action,idempotencyKey:key};const controller=new AbortController();if(scenario==='apply-preabort')controller.abort();results.push(clean(action==='apply'?await host.liveDataApplyAsync(results.length+1,p,controller.signal):await host.liveUndoAsync(results.length+1,p)));states.push(clean(record))}
if(scenario==='expire')record.expiresAt=0;if(scenario==='epoch')sim.reconnect();if(scenario==='identity-edit')sim.state.tracks[0].objectIdentity='other';if(scenario==='data-edit')sim.invoke({operation:'data.set',args:{ref:owner(kind),key:'kumi.test',value:'manual'}});if(scenario.startsWith('apply-')){fault=scenario;fired=false;afterInvoke=false;}
for(const key of ['apply-key','other-key','apply-key'])await perform('apply',key);fault='';fired=false;afterInvoke=false;
if(scenario==='undo-other-identity')sim.state.tracks[0].objectIdentity='other';if(scenario==='undo-other-content')sim.invoke({operation:'data.set',args:{ref:owner(kind),key:'kumi.test',value:'manual'}});if(scenario==='undo-epoch')sim.reconnect();if(scenario.startsWith('undo-')&&!['undo-other-identity','undo-other-content','undo-epoch'].includes(scenario))fault=scenario;
for(const key of ['undo-key','other-undo-key','undo-key'])await perform('undo',key);fault='';fired=false;afterInvoke=false;await perform('undo','new-undo-key')}
workflows.push({kind,scenario,results,states,calls,state:sim.state,saved:sim.invoke({operation:'data.get',args:{ref:owner(kind),key:'kumi.test'}})})}
fs.writeFileSync(new URL('host-data-oracle.json',import.meta.url),JSON.stringify({rows,workflows}));console.log({rows:rows.length,workflows:workflows.length});
